#!/bin/sh
# GENERATED by tools/gen_topology.py - do not edit.
# Runs on every `docker compose up`: initialises Vault once (file storage, survives restarts),
# unseals it, and gives every identity its own folder secret/<name>/, a policy limited to that
# folder and a periodic token (token values come from deployment/.env). Idempotent.
# ponytail: the unseal key sits in a local volume next to Vault; production uses auto-unseal (KMS/HSM).
# ponytail: tokens get fixed ids from .env so EDC config can reference them; Vault then hashes those ids
# with SHA-1 for lookups (it warns). Production: issue tokens via AppRole/Kubernetes auth instead.
set -eu
export VAULT_ADDR=http://vault:8200
INIT=/vault/init/init.txt

if ! wget -qO- "$VAULT_ADDR/v1/sys/init" | grep -q '"initialized":true'; then
  vault operator init -key-shares=1 -key-threshold=1 > "$INIT"
  chmod 600 "$INIT"
  echo "Vault initialised."
fi
vault operator unseal "$(awk '/Unseal Key 1:/ {print $NF}' "$INIT")" > /dev/null
export VAULT_TOKEN="$(awk '/Initial Root Token:/ {print $NF}' "$INIT")"
vault secrets list | grep -q '^secret/' || vault secrets enable -path=secret kv-v2 > /dev/null

identity() { # identity <folder> <token>
  printf 'path "secret/data/%s/*" { capabilities = ["create", "read", "update", "delete", "list"] }\npath "secret/metadata/%s/*" { capabilities = ["read", "list", "delete"] }\n' "$1" "$1" \
    | vault policy write "reed-$1" - > /dev/null
  vault token lookup "$2" > /dev/null 2>&1 \
    || vault token create -id="$2" -policy="reed-$1" -orphan -period=768h -display-name="$1" > /dev/null
  # AES key for IdentityHub/Issuer data encryption: created once, never rotated by this script.
  vault kv get "secret/$1/aes-key-alias" > /dev/null 2>&1 \
    || vault kv put "secret/$1/aes-key-alias" content="$(head -c 32 /dev/urandom | base64)" > /dev/null
}
identity nordvind "$VAULT_TOKEN_NORDVIND"
identity hanse "$VAULT_TOKEN_HANSE"
identity castellum "$VAULT_TOKEN_CASTELLUM"
identity wisla "$VAULT_TOKEN_WISLA"
identity maasvlakte "$VAULT_TOKEN_MAASVLAKTE"
identity rhein-ndt "$VAULT_TOKEN_RHEIN_NDT"
identity komatsu "$VAULT_TOKEN_KOMATSU"
identity federated-catalog "$VAULT_TOKEN_FEDERATED_CATALOG"
identity issuer "$VAULT_TOKEN_ISSUER"
vault kv put secret/nordvind/nordvind-signing-key content=@/keys/nordvind-signing-key.pem > /dev/null
vault kv put secret/nordvind/nordvind-verification-key content=@/keys/nordvind-verification-key.pem > /dev/null
vault kv put secret/nordvind/nordvind-mgmt-api-key content="$MGMT_KEY_NORDVIND" > /dev/null
vault kv put secret/nordvind/nordvind-callback-key content="$CALLBACK_KEY_NORDVIND" > /dev/null
vault kv put secret/hanse/hanse-signing-key content=@/keys/hanse-signing-key.pem > /dev/null
